//! Generates `protocol-js/`: the JS decoders and encoders (and TypeScript
//! types) for the messages between the device and its clients, from the
//! Rust types' postcard schemas (postcard-schema's `#[derive(Schema)]`),
//! plus golden vectors from the Rust encoder for the JS tests.
//!
//!     cargo run -p extreme-bindgen            # write protocol-js/
//!     cargo run -p extreme-bindgen -- --check # fail if it is stale
//!
//! `cargo test` fails too when the committed files are stale. The engine
//! crates embed client bundles that import the generated file, so it is
//! committed rather than written by a build script (which could not run
//! the engines' own types before they are built).

mod js;
mod js_shape;
mod vectors;

use std::{fs, path::PathBuf, process::ExitCode};

use common::protocol::{State, WsEvent, WsState};
use extreme_engines::{EngineEvent, EngineState};
use postcard_schema::Schema;

use js::Export;

const HEADER: &str = "// GENERATED by tools/bindgen (`cargo run -p extreme-bindgen`) from the\n\
// Rust types' postcard schemas: do not edit. The wire format and the JS\n\
// values are described in tools/bindgen/src/js.rs and README.md.";

fn exports() -> Vec<Export> {
    vec![
        Export {
            name: "WsState",
            schema: WsState::<EngineState>::SCHEMA,
            doc: "A state message from the device on the websocket (a binary frame).",
        },
        Export {
            name: "State",
            schema: State::<EngineState>::SCHEMA,
            doc: "A state message from the device on BLE (the `state` characteristic).",
        },
        Export {
            name: "WsEvent",
            schema: WsEvent::<EngineEvent>::SCHEMA,
            doc: "A message to the device on the websocket (a binary frame).",
        },
        Export {
            name: "EngineEvent",
            schema: EngineEvent::SCHEMA,
            doc: "An event to the device on BLE (the `event` characteristic).",
        },
    ]
}

/// The generated files: (path under the repository root, contents).
fn files() -> Vec<(&'static str, String)> {
    let generated = js::generate(&exports(), HEADER);
    let vectors = serde_json::to_string_pretty(&vectors::vectors()).unwrap() + "\n";
    vec![
        ("protocol-js/protocol.js", generated.js),
        ("protocol-js/protocol.d.ts", generated.dts),
        ("protocol-js/test/vectors.json", vectors),
    ]
}

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// The files whose committed contents differ from what is generated now.
fn stale() -> Vec<&'static str> {
    files()
        .into_iter()
        .filter(|(path, contents)| fs::read_to_string(root().join(path)).ok().as_ref() != Some(contents))
        .map(|(path, _)| path)
        .collect()
}

fn main() -> ExitCode {
    if std::env::args().any(|a| a == "--check") {
        let stale = stale();
        if stale.is_empty() {
            return ExitCode::SUCCESS;
        }
        eprintln!("stale: {stale:?}: run `cargo run -p extreme-bindgen`");
        return ExitCode::FAILURE;
    }
    for (path, contents) in files() {
        let path = root().join(path);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(&path, contents).unwrap();
        println!("wrote {}", path.display());
    }
    ExitCode::SUCCESS
}

#[cfg(test)]
mod tests {
    use super::*;
    use common::protocol::MAX_STATE_MESSAGE;
    use extreme_race::{LineView, Phase, RaceView};
    use vectors::{NOW, engine_states};

    #[test]
    fn generated_files_are_current() {
        assert_eq!(stale(), Vec::<&str>::new(), "run `cargo run -p extreme-bindgen`");
    }

    /// Sizes of the BLE `state` value (`State`) in 2026: what a central
    /// must fit in one notification (ATT MTU - 3).
    #[test]
    fn ble_state_sizes() {
        let size = |engine: EngineState| {
            postcard::to_stdvec(&State { timestamp: NOW, engine }).unwrap().len()
        };
        let race = |phase| EngineState::Race(RaceView { speed: 6.4, phase });
        let both = LineView::Both { cross: 50, time: NOW };
        let sizes = [
            ("Selector", size(EngineState::Selector(()))),
            ("Race Active, no line", size(race(Phase::Active { line: LineView::None }))),
            ("Race Active, line both", size(race(Phase::Active { line: both }))),
            ("Race InSequence, no line", size(race(Phase::InSequence { start_time: NOW, line: LineView::None }))),
            ("Race InSequence, line both", size(race(Phase::InSequence { start_time: NOW, line: both }))),
            ("Race Racing", size(race(Phase::Racing { start_time: NOW, heading: 1.0 }))),
            ("TuneSpeed", size(engine_states().last().unwrap().1.clone())),
        ];
        for (what, n) in sizes {
            eprintln!("BLE state, {what}: {n} bytes");
        }
        assert_eq!(
            sizes.map(|(_, n)| n),
            [7, 13, 20, 19, 26, 22, 19]
        );
        // every case in the vectors fits the characteristic
        for (what, engine) in engine_states() {
            let n = postcard::to_stdvec(&State { timestamp: u64::MAX, engine }).unwrap().len();
            assert!(n <= MAX_STATE_MESSAGE, "{what}: {n}");
        }
    }
}
